import java.util.*;

class PatternDictionary {
    private static class Node {
        Node[] next = new Node[26];
        boolean isEnd;
    }

    private final Node root = new Node();

    public PatternDictionary() {
    }

    public void addWord(String word) {
        Node cur = root;
        for (char c : word.toCharArray()) {
            int k = c - 'a';
            if (cur.next[k] == null) cur.next[k] = new Node();
            cur = cur.next[k];
        }
        cur.isEnd = true;
    }

    public boolean search(String pattern) {
        return dfs(root, pattern, 0);
    }

    private boolean dfs(Node node, String p, int i) {
        if (i == p.length()) return node.isEnd; // whole pattern used: a word must end here
        char c = p.charAt(i);
        if (c == '.') {
            for (Node child : node.next) {      // dot: try every branch
                if (child != null && dfs(child, p, i + 1)) return true;
            }
            return false;
        }
        Node child = node.next[c - 'a'];        // letter: only one branch
        return child != null && dfs(child, p, i + 1);
    }
}

